const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lakeBosumtwi = ee.Geometry.Point(-1.408, 6.495).buffer(5000); // Approximate center of Lake Bosumtwi, buffered to cover the lake.

  const date2015_start = '2015-12-01';
  const date2015_end = '2015-12-31';

  // As December 2024 is in the future, we use December 2023 as the most recent comparable December period.
  // This should be noted in the output.
  const date2023_start = '2023-12-01';
  const date2023_end = '2023-12-31';

  // Function to mask clouds and calculate Water Greenness Index (WGI) for Landsat 8/9.
  // WGI = (Green - Red) / (Green + Red) where higher values indicate more greenness.
  // We apply a simple water mask to focus on actual water pixels.
  const processLandsat = function(image) {
    // Apply cloud mask using the QA_PIXEL band (CFMASK).
    // Bits 3 and 5 are cloud shadow and cloud, respectively.
    // Bit 0 is Dilated Cloud (low confidence), Bit 1 is Cloud, Bit 3 is Cloud Shadow, Bit 7 is Snow/Ice.
    // We want to remove clouds, cloud shadows, and snow.
    const qa = image.select('QA_PIXEL');
    const cloudShadowBitmask = 1 << 3;
    const cloudBitmask = 1 << 5;
    const dilatedCloudBitmask = 1 << 1; // Bit 1 for cloud in QA_PIXEL (high confidence)

    const mask = qa.bitwiseAnd(cloudShadowBitmask).eq(0)
                   .and(qa.bitwiseAnd(cloudBitmask).eq(0))
                   .and(qa.bitwiseAnd(dilatedCloudBitmask).eq(0));

    // Select surface reflectance bands and scale them.
    const opticalBands = image.select(['SR_B2', 'SR_B3', 'SR_B4', 'SR_B5', 'SR_B6', 'SR_B7']).multiply(0.0000275).add(-0.2);
    image = image.addBands(opticalBands, null, true);

    // Calculate WGI = (Green - Red) / (Green + Red)
    const green = image.select('SR_B3');
    const red = image.select('SR_B4');
    const wgi = green.subtract(red).divide(green.add(red)).rename('WGI');

    // Simple water mask: Blue band < 0.15 and NIR band < 0.1 (rough estimate for clear water)
    // Or better, NDWI. NDWI = (Green - NIR) / (Green + NIR). Values > 0 are typically water.
    const ndwi = image.normalizedDifference(['SR_B3', 'SR_B5']).rename('NDWI');
    const waterMask = ndwi.gt(0.1); // Adjust threshold if needed for turbid water

    return image.addBands(wgi).updateMask(mask).updateMask(waterMask);
  };

  // 2. Data Acquisition & Check
  const l8_collection_2015 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(lakeBosumtwi)
    .filterDate(date2015_start, date2015_end)
    .map(processLandsat);

  const l8_l9_collection_2023 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .merge(ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')) // Include Landsat 9 for more data in 2023
    .filterBounds(lakeBosumtwi)
    .filterDate(date2023_start, date2023_end)
    .map(processLandsat);

  const count2015 = l8_collection_2015.size().getInfo();
  const count2023 = l8_l9_collection_2023.size().getInfo();

  if (count2015 === 0 || count2023 === 0) {
    console.log(`2015 Images: ${count2015}`);
    console.log(`2023 Images: ${count2023} (used as proxy for 2024)`);
    console.log("No images found for one or both periods after initial filtering.");
    console.log("C1");
    return;
  }

  // Composite images and calculate mean WGI.
  const image2015 = l8_collection_2015.median();
  const image2023 = l8_l9_collection_2023.median();

  // 3. Processing & Calculation
  const scale = 30; // Landsat native resolution

  const getMeanWGI = function(image, geometry, year) {
    // Check if the band exists.
    const bands = image.bandNames().getInfo();
    if (!bands.includes('WGI')) {
      return { mean: null, pixels: 0, year: year };
    }

    const stats = image.select('WGI').reduceRegion({
      reducer: ee.Reducer.count().combine({
        reducer: ee.Reducer.mean(),
        sharedInputs: true
      }),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    });

    const pixelCount = stats.get('WGI_count').getInfo();
    const meanValue = stats.get('WGI_mean').getInfo();

    return { mean: meanValue, pixels: pixelCount, year: year };
  };

  const wgiStats2015 = getMeanWGI(image2015, lakeBosumtwi, 2015);
  const wgiStats2023 = getMeanWGI(image2023, lakeBosumtwi, 2023);

  // 4. Validation & Final Answer
  console.log(`2015 Images: ${count2015}`);
  console.log(`2023 Images: ${count2023} (used as proxy for 2024)`); // Inform about date proxy

  if (wgiStats2015.pixels === 0 || wgiStats2023.pixels === 0) {
    console.log(`2015 Valid Pixels (WGI): ${wgiStats2015.pixels}`);
    console.log(`2023 Valid Pixels (WGI): ${wgiStats2023.pixels}`);
    console.log("No valid pixels remain after masking for one or both periods.");
    console.log("C2");
    return;
  }

  if (wgiStats2015.mean === null || wgiStats2023.mean === null || isNaN(wgiStats2015.mean) || isNaN(wgiStats2023.mean)) {
    console.log(`2015 Mean WGI: ${wgiStats2015.mean}`);
    console.log(`2023 Mean WGI: ${wgiStats2023.mean}`);
    console.log("Calculation resulted in null or NaN for one or both periods.");
    console.log("C3");
    return;
  }

  console.log(`2015 Mean WGI (Greenness Index): ${wgiStats2015.mean.toFixed(4)} (Pixels: ${wgiStats2015.pixels})`);
  console.log(`2023 Mean WGI (Greenness Index): ${wgiStats2023.mean.toFixed(4)} (Pixels: ${wgiStats2023.pixels})`);

  if (wgiStats2023.mean > wgiStats2015.mean) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
